    if isinstance(session.profile, dict):
        profile_data = _handle_intake_extract_dict_profile(session)
    else:
        profile_data = _handle_intake_extract_obj_profile(session)
    evaluator = InputEvaluator()
    is_acceptable, feedback = evaluator.evaluate_profile(profile_data)
    session.step = 'CONFIRM'
    confirmation_msg = _format_playback(session)
    if not feedback:
        return confirmation_msg
    feedback_msg = '\n\n📝 *Input Feedback:*\n' + '\n'.join(feedback)
