def _get_clashed_elements(branches: PillarMap) -> set[str]:
    natal_branches = [b for b in (branches.year, branches.month, branches.day, branches.hour) if b]
    ext_branches = [b for b in (branches.transit_month, branches.transit_year) if b]
    elements = (_get_branch_clash_element(b, ext_branches) for b in natal_branches)
    return {el for el in elements if el}

helper_functions:
def _get_branch_clash_element(natal_b: str, ext_branches: list[str]) -> str | None:
    b_info = get_branch_info(natal_b)
    if not b_info:
        return None
    if any(get_chong(ext_b) == natal_b for ext_b in ext_branches):
        return b_info.element.value
    return None

