def _handle_intake_is_reset(session, cmd: str) -> bool:
    if cmd == '/reset':
        return True
    return cmd == '/input' and session.step == 'COMPLETE'

def _handle_intake_global_commands(session, text: str):
    cmd = text.lower()
    if _handle_intake_is_reset(session, cmd):
        session.step = 'START'
        session.profile = None
        session.metadata = {}
        session.conversation_history = []
        if cmd == '/reset':
            return '♻️ Session reset. Type /start to begin again.'

    if cmd == '/help':
        return HELP_TEMPLATE
    if cmd == '/tips':
        evaluator = InputEvaluator()
        return evaluator.get_tone_advice()
    return None

async def _handle_intake_start_and_choosing(session, chat_id: int, text: str, platform: str):
    if text.lower() == '/start':
        session.step = 'CHOOSING'
        return _handle_intake_welcome_prompt()

    if session.step not in ('START', 'CHOOSING'):
        return None
    if text.startswith('/'):
        return None

    if _looks_like_bazi_profile(text):
        return _handle_intake_bazi_start(session, chat_id, platform)

    return 'Please select an option above to begin.'

async def _handle_intake_start_auto_or_input(session, chat_id: int, mode: str, platform: str, check_security: bool):
    if check_security:
        from src2.interfaces.telegram.security import can_generate_report
        if not can_generate_report(chat_id, platform=platform):
            return '🔑 *Report Locked.*\n\nPlease enter your promo code to generate your monthly forecast report.'
    session.metadata.intake_mode = mode
    session.conversation_history = []
    session.step = 'COLLECTING'
    if mode == 'input':
        return HELP_TEMPLATE
    return await _handle_intake_run_auto(session, chat_id)

async def _handle_intake_early_flow(session, chat_id: int, text: str, platform: str):
    res = _handle_intake_global_commands(session, text)
    if res is not None:
        return res

    res = await _handle_intake_start_and_choosing(session, chat_id, text, platform)
    if res is not None:
        return res

    if text.lower() in ('/auto', '/input'):
        mode = 'auto' if 'auto' in text.lower() else 'input'
        return await _handle_intake_start_auto_or_input(session, chat_id, mode, platform, check_security=True)

    return None

async def _handle_intake_choosing_step(session, chat_id: int, text: str, platform: str):
    if text.lower() in ['/auto', 'auto', '/input', 'input']:
        mode = 'auto' if 'auto' in text.lower() else 'input'
        check_security = text.startswith('/')
        return await _handle_intake_start_auto_or_input(session, chat_id, mode, platform, check_security=check_security)
    return 'Please select /auto or /input to begin.'

def _handle_intake_calendar_exception(e: Exception, session, platform: str) -> str:
    re = __import__('re')
    err_msg = str(e)
    if 'validation error' in err_msg.lower():
        match = re.search('Value error,\\s*([^\\n\\[]+)', err_msg)
        if match:
            err_msg = match.group(1).strip()
    session.profile = None
    save_session(session, platform)
    return f'⚠️ *Validation failed for manual entry:*\n\n- {err_msg}\n\nPlease correct these parameters and send again.'

def _handle_intake_dict_pillars(session) -> dict:
    yp = session.profile.get('year_pillar', {})
    mp = session.profile.get('month_pillar', {})
    dp = session.profile.get('day_pillar', {})
    return {
        'year': f"{yp.get('stem', '')} {yp.get('branch', '')}".strip() if yp else '',
        'month': f"{mp.get('stem', '')} {mp.get('branch', '')}".strip() if mp else '',
        'day': f"{dp.get('stem', '')} {dp.get('branch', '')}".strip() if dp else '',
    }

def _handle_intake_obj_pillars(session) -> dict:
    return {
        'year': f'{session.profile.year_pillar.stem} {session.profile.year_pillar.branch}'.strip() if session.profile and session.profile.year_pillar else '',
        'month': f'{session.profile.month_pillar.stem} {session.profile.month_pillar.branch}'.strip() if session.profile and session.profile.month_pillar else '',
        'day': f'{session.profile.day_pillar.stem} {session.profile.day_pillar.branch}'.strip() if session.profile and session.profile.day_pillar else '',
    }

def _handle_intake_evaluate_and_confirm(session) -> str:
    if isinstance(session.profile, dict):
        profile_data = _handle_intake_extract_dict_profile(session)
    else:
        profile_data = _handle_intake_extract_obj_profile(session)
    evaluator = InputEvaluator()
    is_acceptable, feedback = evaluator.evaluate_profile(profile_data)
    session.step = 'CONFIRM'
    confirmation_msg = _format_playback(session)
    if not feedback:
        return confirmation_msg
    feedback_msg = '\n\n📝 *Input Feedback:*\n' + '\n'.join(feedback)
    if not is_acceptable:
        feedback_msg += '\n\n⚠️ *Note:* Some critical information is missing, but you can still proceed. For best results, consider correcting the issues above.'
    feedback_msg += f'\n\n{evaluator.get_tone_advice()}'
    return confirmation_msg + feedback_msg

async def _handle_intake_calendar_and_validate(session, platform: str):
    try:
        session = await run_calendar_node(session)
    except Exception as e:
        return _handle_intake_calendar_exception(e, session, platform)

    from src2.interfaces.telegram.bridge import validate_profile
    is_valid, errors = validate_profile(session.profile)
    if not is_valid:
        session.profile = None
        save_session(session, platform)
        return '⚠️ *Validation failed for manual entry:*\n\n' + '\n'.join((f'- {e}' for e in errors)) + '\n\nPlease correct these parameters and send again.'

    return _handle_intake_evaluate_and_confirm(session)

