def validate_month_output(month_data: dict) -> list[dict]:
    """
    Validate a single month's LLM output against deterministic rules.
    Returns a list of violation dicts. Empty list = PASS.
    """
    violations = []
    month_name = month_data.get('month', month_data.get('month_name', 'Unknown'))
    ctx = f'Month: {month_name}'
    required_keys = ['month', 'assembled_narrative', 'advisory']
    for key in required_keys:
        if key == 'month' and 'month_name' in month_data:
            continue
        if key not in month_data:
            violations.append({'rule_id': 'MISSING_KEY', 'detail': f"[{ctx}] Missing required key: '{key}'", 'fix': f"Add '{key}' to the output JSON."})
    narrative = month_data.get('assembled_narrative', '')
    wc = _word_count(narrative)
    if wc < MIN_WORDS_NARRATIVE:
        violations.append({'rule_id': 'NARRATIVE_TOO_SHORT', 'detail': f'[{ctx}] assembled_narrative is {wc} words (min: {MIN_WORDS_NARRATIVE}).', 'fix': f'Expand the narrative to at least {MIN_WORDS_NARRATIVE} words.'})
    advisory = month_data.get('advisory', {})
    if isinstance(advisory, dict):
        for domain in ['career', 'marriage', 'health', 'wealth']:
            section_text = advisory.get(domain, '')
            wc = _word_count(section_text)
            if wc < MIN_WORDS_ADVISORY_SECTION:
                violations.append({'rule_id': 'ADVISORY_TOO_SHORT', 'detail': f'[{ctx}] advisory.{domain} is {wc} words (min: {MIN_WORDS_ADVISORY_SECTION}).', 'fix': f'Expand {domain} advisory to at least {MIN_WORDS_ADVISORY_SECTION} words.'})
    all_text = json.dumps(month_data, ensure_ascii=False)
    violations.extend(_check_banned_words(all_text, ctx))
    violations.extend(_check_required_vocab(narrative, f'{ctx} narrative', min_terms=2))
    rationale = month_data.get('rationale', '')
    if rationale and _word_count(rationale) < MIN_WORDS_RATIONALE:
        violations.append({'rule_id': 'RATIONALE_TOO_SHORT', 'detail': f'[{ctx}] rationale is {_word_count(rationale)} words (min: {MIN_WORDS_RATIONALE}).', 'fix': f'Expand rationale to at least {MIN_WORDS_RATIONALE} words.'})
    module8 = month_data.get('module8', {})
    if isinstance(module8, dict) and 'composite_score' in module8:
        score = module8['composite_score']
        try:
            num_score = float(score)
            if num_score > 80.0 or num_score < 35.0:
                violations.append({'rule_id': 'SCORE_OUT_OF_BOUNDS', 'detail': f'[{ctx}] composite_score {num_score} is outside the allowed system range [35.0, 80.0].', 'fix': 'Recalculate or clamp the composite score to be within valid range.'})
        except (ValueError, TypeError):
            pass
        if 'rating' in module8:
            expected_rating = score_to_rating(int(module8['composite_score']))
            if module8['rating'] != expected_rating:
                violations.append({'rule_id': 'SCORE_RATING_MISMATCH', 'detail': f"[{ctx}] Score {module8['composite_score']} should map to '{expected_rating}', got '{module8['rating']}'.", 'fix': f"Change rating to '{expected_rating}'."})
    citations = month_data.get('classical_citations', [])
    if isinstance(citations, list):
        valid_sources = {'yuan hai zi ping', 'san ming tong hui', 'di tian sui', 'qiong tong bao jian', '渊海子平', '三命通会', '滴天髓', '穷通宝鉴', '窮通寶鑑', '淵海子平', '三命通會'}
        for i, cite in enumerate(citations):
            if isinstance(cite, dict):
                source = cite.get('source_text', '').lower().strip()
                if source and (not any((vs in source for vs in valid_sources))):
                    violations.append({'rule_id': 'UNKNOWN_CITATION_SOURCE', 'detail': f"[{ctx}] Citation {i + 1} references unknown source: '{cite.get('source_text', '')}'", 'fix': 'Citations must reference: Yuan Hai Zi Ping, San Ming Tong Hui, Di Tian Sui, or Qiong Tong Bao Jian.'})
    return violations

