def extract_header_symbol_contract(source: str) -> HeaderSymbolContract:
    """Parse full file AST to extract all imported module names, imported symbols, top-level functions/classes, and global constants."""
    if not source:
        return HeaderSymbolContract()
    try:
        tree = ast.parse(source)
    except Exception:
        return HeaderSymbolContract()

    imported_modules: set[str] = set()
    imported_symbols: set[str] = set()
    top_level_symbols: set[str] = set()
    global_constants: set[str] = set()

    for node in tree.body:
        _extract_header_symbol_contract_process_node(
            node, imported_modules, imported_symbols, top_level_symbols, global_constants
        )

    return HeaderSymbolContract(
        imported_modules=sorted(imported_modules),
        imported_symbols=sorted(imported_symbols),
        top_level_symbols=sorted(top_level_symbols),
        global_constants=sorted(global_constants),
    )

helper_functions:
def _extract_header_symbol_contract_process_import(
    node: Any, imported_modules: set, imported_symbols: set
) -> None:
    for alias in node.names:
        imported_modules.add(alias.name)
        bound_name = alias.asname or alias.name.split(".")[0]
        imported_symbols.add(bound_name)

def _extract_header_symbol_contract_process_import_from(
    node: Any, imported_modules: set, imported_symbols: set
) -> None:
    if node.module:
        imported_modules.add(node.module)
    for alias in node.names:
        if alias.name != "*":
            bound_name = alias.asname or alias.name
            imported_symbols.add(bound_name)

def _extract_header_symbol_contract_process_assign(
    node: Any, global_constants: set
) -> None:
    for target in node.targets:
        if isinstance(target, ast.Name):
            global_constants.add(target.id)

def _extract_header_symbol_contract_process_node(
    node: Any,
    imported_modules: set,
    imported_symbols: set,
    top_level_symbols: set,
    global_constants: set,
) -> None:
    if isinstance(node, ast.Import):
        _extract_header_symbol_contract_process_import(node, imported_modules, imported_symbols)
    elif isinstance(node, ast.ImportFrom):
        _extract_header_symbol_contract_process_import_from(node, imported_modules, imported_symbols)
    elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        top_level_symbols.add(node.name)
    elif isinstance(node, ast.Assign):
        _extract_header_symbol_contract_process_assign(node, global_constants)

