def __collect_function_locals_args(fn_node: Any, scope: set[str]) -> None:
    args_node = fn_node.args
    for arg in args_node.posonlyargs + args_node.args + args_node.kwonlyargs:
        scope.add(arg.arg)
    if args_node.vararg:
        scope.add(args_node.vararg.arg)
    if args_node.kwarg:
        scope.add(args_node.kwarg.arg)

def __collect_function_locals_name(node: Any, scope: set[str]) -> bool:
    if isinstance(node, ast.Name):
        if isinstance(node.ctx, (ast.Store, ast.Param)):
            scope.add(node.id)
            return True
    return False

def __collect_function_locals_except(node: Any, scope: set[str]) -> bool:
    if isinstance(node, ast.ExceptHandler):
        if node.name:
            scope.add(node.name)
            return True
    return False

def __collect_function_locals_import(node: Any, scope: set[str]) -> bool:
    if isinstance(node, (ast.Import, ast.ImportFrom)):
        for alias in node.names:
            bound = alias.asname or alias.name.split(".")[0]
            scope.add(bound)
        return True
    return False

def __collect_function_locals_def(node: Any, fn_node: Any, scope: set[str]) -> None:
    if node is fn_node:
        return
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        scope.add(node.name)

def __collect_function_locals_node(node: Any, fn_node: Any, scope: set[str]) -> None:
    if __collect_function_locals_name(node, scope):
        return
    if __collect_function_locals_except(node, scope):
        return
    if __collect_function_locals_import(node, scope):
        return
    __collect_function_locals_def(node, fn_node, scope)

def __visit_function_visit_all_args(visitor: Any, args_node: Any) -> None:
    all_args = args_node.posonlyargs + args_node.args + args_node.kwonlyargs
    for arg in all_args:
        __visit_function_visit_arg_annotation(visitor, arg)
    __visit_function_visit_arg_annotation(visitor, args_node.vararg)
    __visit_function_visit_arg_annotation(visitor, args_node.kwarg)

def __visit_function_visit_defaults(visitor: Any, args_node: Any) -> None:
    for default in args_node.defaults:
        visitor.visit(default)
    for default in args_node.kw_defaults:
        if default:
