def __check_body_nesting_inspect_try_body(stmt: ast.Try) -> list[tuple[int, str]]:
    issues: list[tuple[int, str]] = []
    for inner in stmt.body:
        if isinstance(inner, ast.Try):
            issues.append((inner.lineno, "Nested Try block inside Try body"))
    return issues

def __check_body_nesting_inspect_try_handlers(stmt: ast.Try) -> list[tuple[int, str]]:
    issues: list[tuple[int, str]] = []
    for handler in stmt.handlers:
        for h_stmt in handler.body:
            if isinstance(h_stmt, ast.Try):
                issues.append((h_stmt.lineno, "Try block inside Except handler"))
    return issues

def __check_body_nesting_inspect_try_orelse(stmt: ast.Try) -> list[tuple[int, str]]:
    if not stmt.orelse:
        return []
    issues: list[tuple[int, str]] = []
    for el_stmt in stmt.orelse:
        if isinstance(el_stmt, (ast.If, ast.Try)):
            issues.append((el_stmt.lineno, f"{el_stmt.__class__.__name__} inside Try-Else block"))
    return issues

def __check_body_nesting_get_if_sub_bodies(
    stmt: ast.If, current_depth: int, depth: int
) -> list[tuple[list[ast.stmt], int]]:
    sub_bodies: list[tuple[list[ast.stmt], int]] = [(stmt.body, current_depth)]
    if len(stmt.orelse) == 1 and isinstance(stmt.orelse[0], ast.If):
        sub_bodies.append((stmt.orelse, depth))
    else:
        sub_bodies.append((stmt.orelse, current_depth))
    return sub_bodies

def __check_body_nesting_get_try_sub_bodies(
    stmt: ast.Try, current_depth: int
) -> list[tuple[list[ast.stmt], int]]:
    sub_bodies: list[tuple[list[ast.stmt], int]] = [(stmt.body, current_depth)]
    for h in stmt.handlers:
        sub_bodies.append((h.body, current_depth))
    sub_bodies.append((stmt.orelse, current_depth))
    sub_bodies.append((stmt.finalbody, current_depth))
    return sub_bodies

def __check_body_nesting_extract_sub_bodies(
    stmt: ast.stmt, current_depth: int, depth: int
) -> list[tuple[list[ast.stmt], int]]:
    if isinstance(stmt, ast.If):
        return __check_body_nesting_get_if_sub_bodies(stmt, current_depth, depth)
    if isinstance(stmt, ast.Try):
        return __check_body_nesting_get_try_sub_bodies(stmt, current_depth)
    if isinstance(stmt, (ast.For, ast.While)):
        return [(stmt.body, current_depth), (stmt.orelse, current_depth)]
    if isinstance(stmt, ast.With):
        return [(stmt.body, current_depth)]
    return []

