def _verify_refactored_ast_check_single_call(
    new_call: tuple[str, tuple[str, ...]],
    orig_func_names: set[str],
    orig_calls: set[tuple[str, tuple[str, ...]]],
    new_kw: set[str],
    orig_kw: set[str],
) -> str | None:
    func_name, new_args = new_call
    if func_name not in orig_func_names:
        return None
    if new_call in orig_calls:
        return None
    if func_name in new_kw:
        return None
    if func_name in orig_kw:
