def _verify_refactored_ast_get_non_builtin_call_names(calls: set[tuple[str, tuple[str, ...]]], builtin_methods: set[str]) -> set[str]:
    names: set[str] = set()
    for call in calls:
        if call[0] not in builtin_methods:
            names.add(call[0])
    return names

def _verify_refactored_ast_check_calls(tree: Any, orig_code: str) -> list[str]:
    violations: list[str] = []
    if not orig_code:
        return violations
    try:
        builtin_methods = {
            "isinstance", "getattr", "hasattr", "setattr", "len", "str", "int", "float", "bool",
            "list", "dict", "set", "tuple", "any", "all", "print", "type", "range", "enumerate",
            "zip", "min", "max", "sum", "sorted", "reversed", "super", "get", "append", "extend",
            "gather", "add", "update", "model_validate", "model_dump", "parse_mode", "format",
            "encode", "decode", "split", "strip", "join", "replace", "startswith", "endswith",
            "lower", "upper", "create_task", "add_done_callback", "discard", "getLogger",
            "from_url", "aclose", "model_validate_json", "strftime", "isoformat", "run"
        }
        orig_tree = ast.parse(orig_code)
        orig_call_vis = CallVisitor()
        orig_call_vis.visit(orig_tree)
        new_call_vis = CallVisitor()
        new_call_vis.visit(tree)
        orig_func_names = _verify_refactored_ast_get_non_builtin_call_names(orig_call_vis.calls, builtin_methods)
        for new_call in new_call_vis.calls:
            v = _verify_refactored_ast_check_single_call(
                new_call, orig_func_names, orig_call_vis.calls, new_call_vis.calls_with_keywords, orig_call_vis.calls_with_keywords
            )
            if v:
                violations.append(v)
    except Exception:
        pass
    return violations

def _verify_refactored_ast_is_target_func(node: Any, name: str) -> bool:
    if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return False
    return node.name == name

def _verify_refactored_ast_find_func_node(tree: Any, name: str) -> Any:
    for n in ast.walk(tree):
