    return None

def _verify_refactored_ast_compare_signatures(orig_sig: dict, ref_sig: dict, candidate_name: str) -> list[str]:
    if orig_sig == ref_sig:
        return []
    violations: list[str] = []
    for k, v in orig_sig.items():
        if ref_sig.get(k) != v:
            sugg = _verify_refactored_ast_get_suggestion(f"signature_{k}")
            violations.append(f"signature_mismatch:{candidate_name}:{k} | Suggestion: {sugg}")
    return violations

def _verify_refactored_ast_do_check_signature(tree: Any, orig_code: str, candidate_name: str) -> list[str]:
    orig_tree = ast.parse(orig_code)
