    ref_main_node = _verify_refactored_ast_find_func_node(tree, candidate_name)
    if not ref_main_node:
        sugg = _verify_refactored_ast_get_suggestion("missing_function")
        return [f"missing_function: The main target function `{candidate_name}` is missing or renamed in refactored code | Suggestion: {sugg}"]
    return _verify_refactored_ast_compare_signatures(
        extract_function_signature(orig_main_node), extract_function_signature(ref_main_node), candidate_name
    )

def _verify_refactored_ast_check_signature(tree: Any, orig_code: str, candidate_name: str) -> list[str]:
    if not orig_code:
