    Compares ALL signal pairs (not just first two).
    """
    if len(paradox_signals) < 2:
        return ContradictionResolution(resolved=False, reason="insufficient_signals", resolution=None)

    classifications = _resolve_paradox_four_step_classify_pairs(paradox_signals)
