def _resolve_paradox_four_step_signal_sort_key(signal: ContradictionSignal) -> tuple[int, float]:
    rank = signal.evidence_rank
    if rank is None:
        rank = 4
    weight = signal.temporal_weight
    if weight is None:
        weight = 1.0
    return (rank, -weight)

def _resolve_paradox_four_step_classify_pairs(
    paradox_signals: list[ContradictionSignal],
) -> list[ContradictionClassification]:
    classifications = []
    n = len(paradox_signals)
    for i in range(n):
        for j in range(i + 1, n):
            cls = classify_contradiction(paradox_signals[i], paradox_signals[j])
            cls.pair = (i, j)
            classifications.append(cls)
    return classifications

def _resolve_paradox_four_step_rank_signals(
    paradox_signals: list[ContradictionSignal],
) -> list[ContradictionSignal]:
    ranked = apply_hierarchy_of_evidence(paradox_signals)
    for s in ranked:
        dist = s.temporal_distance
        if dist is None:
            dist = 0.0
        s.temporal_weight = calculate_temporal_weight(dist)
    ranked.sort(key=_resolve_paradox_four_step_signal_sort_key)
    return ranked

def _resolve_paradox_four_step_build_resolution(
    classifications: list[ContradictionClassification],
