) -> ContradictionResolution:
    rank_val = winner_signal.evidence_rank
    if rank_val is None:
        rank_val = 4

    source = winner_signal.source
    if not source:
        source_str = "unknown"
        msg_str = "?"
    else:
        source_str = source
        msg_str = source

    confidence = "medium"
    if rank_val <= 2:
        confidence = "high"

    return ContradictionResolution(
        resolved=True,
        classifications=classifications,
        winner=source_str,
        confidence=confidence,
        resolution=f"Signal from '{msg_str}' takes precedence",
