async def _agent_webhook_validate_secret(request: Request):
    agent_secret = (os.getenv('AGENT_WEBHOOK_SECRET') or '').strip()
    if not agent_secret:
        logger.error('CRITICAL: AGENT_WEBHOOK_SECRET not set in .env! Refusing unprotected agent webhook.')
        return JSONResponse(status_code=500, content={'status': 'error', 'message': 'Server configuration error'})
    secret_header = request.headers.get('X-Telegram-Bot-Api-Secret-Token')
