        src = s.source or ""
        if src in source_hierarchy:
            s.classical_priority = source_hierarchy[src]["priority"]
        else:
            s.classical_priority = 99

def _get_priority(sig: ContradictionSignal) -> int:
    val = sig.classical_priority
    if val is None:
        return 99
    return val

def _resolve_contradictions_get_classical_resolution(
    sig_a: ContradictionSignal, sig_b: ContradictionSignal
) -> dict[str, str] | None:
    p_a = _get_priority(sig_a)
    p_b = _get_priority(sig_b)
    if p_a >= 99:
        return None
    if p_b >= 99:
        return None
    if p_a < p_b:
        return {"winner": "signal_a", "reason": "higher_classical_authority"}
    if p_b < p_a:
        return {"winner": "signal_b", "reason": "higher_classical_authority"}
    return None

def _resolve_contradictions_find_contradictions(signals: list[ContradictionSignal]) -> list[ContradictionEntry]:
    contradictions = []
    for i in range(len(signals)):
        for j in range(i + 1, len(signals)):
            if signals[i].direction != signals[j].direction:
                classification = classify_contradiction(signals[i], signals[j])
                paradox_check = classify_true_vs_apparent(signals[i], signals[j])
                classical_res = _resolve_contradictions_get_classical_resolution(signals[i], signals[j])
                contradictions.append(
                    ContradictionEntry(
                        signal_a=signals[i],
                        signal_b=signals[j],
                        classification=classification,
                        paradox_classification=paradox_check,
                        classical_resolution=classical_res,
                    )
                )
    return contradictions

def _resolve_contradictions_apply_weights_and_patterns(
    contradictions: list[ContradictionEntry], profile: ChartProfile
) -> None:
    for c in contradictions:
        c.weight_a = calculate_temporal_weight(c.signal_a.temporal_distance or 0)
        c.weight_b = calculate_temporal_weight(c.signal_b.temporal_distance or 0)
        c.pattern_match = _match_pattern(c, profile)

def _resolve_contradictions_append_override_synthesis(
    synthesis: list, override_trace: list[str]
) -> None:
    for msg in override_trace:
        synthesis.append(
            ContradictionSynthesis(
                conflict="Severe Clash vs Weak Combination",
                type="clash_override",
                resolution="override",
                dominant="Severe Clash Dominance",
                winner="Severe Clash",
                loser="Weak Combination",
                statement=msg,
            )
        )

