def _run_full_engine_extracted_3_handle_combination(
    _interaction: Any, transformed_branches: Any, chart_branches: Any
) -> None:
    if not _interaction.is_successful:
        return
    _el = _interaction.resultant_element
    if not _el:
        return
    for _b in _interaction.actors:
        if not transformed_branches.has_state(_b, chart_branches):
            transformed_branches.set_branch_state(_b, _el, chart_branches)

def _run_full_engine_extracted_3_handle_clash(
    _interaction: Any, transformed_branches: Any, chart_branches: Any
) -> None:
    for _b in _interaction.actors:
        if not transformed_branches.has_state(_b, chart_branches):
            transformed_branches.set_branch_state(_b, 'UNSTABLE', chart_branches)

def _run_full_engine_extracted_3_process_interaction(
    _interaction: Any, transformed_branches: Any, chart_branches: Any
) -> None:
    if _interaction.vector in ['SanHe', 'SanHui', 'BanHe', 'LiuHe', 'WuHe']:
        _run_full_engine_extracted_3_handle_combination(_interaction, transformed_branches, chart_branches)
    elif _interaction.vector in ['Chong', 'Xing', 'Hai', 'Po', 'SelfPunish']:
        _run_full_engine_extracted_3_handle_clash(_interaction, transformed_branches, chart_branches)

