def _run_full_engine_extracted_6_should_process(interaction: Any) -> bool:
    if interaction.vector not in ("LiuHe", "SanHe", "SanHui", "BanHe"):
        return False
    if not interaction.is_successful:
        return False
    return bool(interaction.resultant_element)

