def run_full_engine_extracted_5(interaction_results: Any, _chart_stems_list: Any) -> list:
    harmony_strengths = []
    calc_fn = globals()['calculate_harmony_strength']
    for _interaction in interaction_results.all_interactions:
        if _interaction.vector != "LiuHe":
            continue
        if not _interaction.is_successful:
            continue
        _branches = _interaction.actors
        if len(_branches) < 2:
            continue
        _hs = calc_fn(_branches[0], _branches[1], _chart_stems_list)
        harmony_strengths.append(_hs)
    return harmony_strengths

