def run_full_engine_extracted_7(
    interaction_results,
    _harms_for_damage,
    _punishments_for_damage,
    _clashes_for_damage,
):
    item_cls = globals()['DamageInputItem']
    target_map = {
        'Hai': _harms_for_damage,
        'Xing': _punishments_for_damage,
        'Chong': _clashes_for_damage,
    }
    for _interaction in interaction_results.all_interactions:
        _sev = _interaction.potency * 10
        if _sev <= 0:
            continue
        target_list = target_map.get(_interaction.vector)
        if target_list is None:
            continue
        for _b in _interaction.actors:
            target_list.append(item_cls(severity=_sev, branch=_b))

