def __run_full_engine_setup_dayun_resolve_pillar(da_yun_data: Any) -> Pillar:
    active_cycle = get_current_da_yun(da_yun_data)
    if active_cycle:
        return Pillar(stem=active_cycle.stem, branch=active_cycle.branch)
    return Pillar(stem="Unknown", branch="Unknown")

def __run_full_engine_setup_dayun_ensure_pillar(profile: ChartProfile, da_yun_data: Any) -> None:
    if profile.da_yun_pillar and profile.da_yun_pillar.stem != "Unknown":
        return
    profile.da_yun_pillar = __run_full_engine_setup_dayun_resolve_pillar(da_yun_data)

def __run_full_engine_setup_dayun_calc_months(da_yun_data: Any) -> Any:
    if not da_yun_data.start_year:
        return None
    today = get_sg_today()
    dayun_start = da_yun_data.start_date or date(int(da_yun_data.start_year), 1, 1)
    return max(0, (today.year - dayun_start.year) * 12 + (today.month - dayun_start.month))

